Part B — download through the API (added; not part of govtdata01.R)
Uses the search, package-summary and paging endpoints from section 2. Writes the PDFs to govinfo_pdfs/ (add it to .gitignore) and a download log to assign05_download_log.csv, which is the file to post. The key is read from .Renviron and never written to the log.

B1. Setup

library(httr2)
library(purrr)
library(dplyr)
library(readr)

api_key &lt;- Sys.getenv("GOVINFO_API_KEY")
if (api_key == "") stop("GOVINFO_API_KEY not found. Add it to .Renviron and restart R.")

pdf_dir  &lt;- "govinfo_pdfs"               # listed in .gitignore
log_file &lt;- "assign05_download_log.csv"  # posted with the report
dir.create(pdf_dir, showWarnings = FALSE)

# Base request: every call goes to api.govinfo.gov and carries api_key
govinfo &lt;- function(path) {
  request("https://api.govinfo.gov") |&gt;
    req_url_path_append(path) |&gt;
    req_url_query(api_key = api_key) |&gt;
    req_retry(max_tries = 3)
}



B2. Search, page, and keep the first ten Senate Foreign Relations hearings
The full-text query also matches hearings of other committees that merely mention the Committee on Foreign Relations, so each candidate’s summary is checked for the committee itself.

search_page &lt;- function(offset) {
  govinfo("search") |&gt;
    req_body_json(list(
      query      = 'collection:(CHRG) AND "Committee on Foreign Relations"',
      pageSize   = 100,
      offsetMark = offset,
      sorts      = list(list(field = "publishdate", sortOrder = "DESC"))
    )) |&gt;
    req_perform() |&gt;
    resp_body_json()
}

get_summary &lt;- function(id) {
  govinfo(paste0("packages/", id, "/summary")) |&gt;
    req_perform() |&gt;
    resp_body_json()
}

is_sfrc &lt;- function(s) {
  any(map_lgl(s$committees %||% list(), \(cm)
    identical(toupper(cm$chamber %||% ""), "SENATE") &&
      grepl("Foreign Relations", cm$committeeName %||% "", ignore.case = TRUE)))
}

n_target &lt;- 10
hearings &lt;- list()
seen     &lt;- character()
offset   &lt;- "*"

while (length(hearings) &lt; n_target) {
  page &lt;- search_page(offset)
  if (length(page$results) == 0) break          # no more results: stop

  for (r in page$results) {
    id &lt;- r$packageId
    if (is.null(id) || id %in% seen) next        # skip granules already seen
    seen &lt;- c(seen, id)
    s &lt;- get_summary(id)
    Sys.sleep(0.5)
    if (is_sfrc(s)) hearings[[id]] &lt;- s
    if (length(hearings) == n_target) break
  }

  if (is.null(page$offsetMark) || identical(page$offsetMark, offset)) break
  offset &lt;- page$offsetMark                      # send it back for the next page
}

message(length(hearings), " hearings found after checking ", length(seen), " packages")



B3. Metadata table — what you get without opening a file

hearing_tbl &lt;- map_dfr(hearings, \(s) tibble(
  packageId  = s$packageId,
  title      = s$title %||% NA_character_,
  dateIssued = s$dateIssued %||% NA_character_,
  heldDates  = paste(unlist(s$heldDates), collapse = "; "),
  congress   = as.character(s$congress %||% NA),
  pdfLink    = s$download$pdfLink  %||% paste0("https://api.govinfo.gov/packages/", s$packageId, "/pdf"),
  txtLink    = s$download$txtLink  %||% paste0("https://api.govinfo.gov/packages/", s$packageId, "/htm"),
  modsLink   = s$download$modsLink %||% paste0("https://api.govinfo.gov/packages/", s$packageId, "/mods")
))
hearing_tbl



B4. Download the PDFs and write the log

download_pdf &lt;- function(id, url) {
  dest    &lt;- file.path(pdf_dir, paste0(id, ".pdf"))
  started &lt;- format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z")

  res &lt;- if (is.na(url)) {
    list(status = "no pdfLink", http = NA_integer_, error = NA_character_)
  } else {
    tryCatch({
      resp &lt;- request(url) |&gt;
        req_url_query(api_key = api_key) |&gt;
        req_retry(max_tries = 3) |&gt;
        req_perform(path = dest)
      list(status = "ok", http = resp_status(resp), error = NA_character_)
    }, error = \(e) list(status = "failed", http = NA_integer_,
                         error = conditionMessage(e)))
  }
  Sys.sleep(runif(1, 1, 3))  # polite pause, as in govtdata01.R

  tibble(
    packageId   = id,
    pdf_url     = url,                       # without the key
    file        = dest,
    status      = res$status,
    http_status = res$http,
    bytes       = if (res$status == "ok") file.size(dest) else NA_real_,
    error       = res$error,
    started     = started
  )
}

download_log &lt;- map2_dfr(hearing_tbl$packageId, hearing_tbl$pdfLink, download_pdf) |&gt;
  left_join(select(hearing_tbl, packageId, title, dateIssued, heldDates),
            by = "packageId")

write_csv(download_log, log_file)
count(download_log, status)



B5. Compare with the hand export (section 3c)
Uses the CSV exported in section 1.

export_file &lt;- "govinfo-search-results-2026-10-10T18_45_50.csv"
export_ids  &lt;- read.csv(export_file, skip = 2)$packageId |&gt; unique() |&gt; head(n_target)
api_ids     &lt;- hearing_tbl$packageId

list(
  in_both          = intersect(export_ids, api_ids),
  only_hand_export = setdiff(export_ids, api_ids),
  only_api         = setdiff(api_ids, export_ids)
)

